#### 15. 三数之和
(https://leetcode.cn/problems/3sum/)
优化前：
```cpp
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> ans;
        int n = nums.size();
        for (int i = 0;i < n - 2;i++) {
            int x = nums[i];
            if (i && x == nums[i - 1]) continue;
            int left = i + 1, right = n - 1;
            while (left < right) {
                int s = nums[right] + nums[left] + x;
                if (s > 0) right--;
                else if (s < 0) left++;
                else {
                    ans.emplace_back(vector<int>{nums[i], nums[left], nums[right]});
                    for (left++;left < right && nums[left] == nums[left - 1]; left++);
                    for (right--;left < right && nums[right] == nums[right + 1];right--);
                }
            }
        }
        return ans;
    }
};
```
使用[[题型分类#相向双指针]]思想:
- `If(i && x == nums[i - 1]) continue;` 将重复值跳过比较，由于使用 sort 后相同的元素一定相邻，所以重复的情况可以用 `nums[i] == nums[i - 1]` 比较，也防止了溢出
![[Pasted image 20250215222848.png|350]]
![[Pasted image 20250215221822.png]]
- 如果 `[curren]t+[left]+[right] ? 0` 通过[[题型分类#双指针法#167. 两数之和 II - 输入有序数组]]可知比较的结果决定了 left 或者 right 的移动
- 外层循环推动 current，内层推动 left 和 right 的靠拢
- 找到一个答案三元组添加 ans 中后，还需要继续判断 left 和 right 之间有没有 answer
```cpp
for (left++;left < right && nums[left] == nums[left - 1]; left++);
for (right--;left < right && nums[right] == nums[right + 1];right--);
// 这里使用两个for将left和right跳转到没有重复相邻元素的位置，进入下一循环
```
- 其中找到下一个没有重复元素的位置时，`left < right` 必须有且在 `nums[left] == nums[left - 1]` 前面，没有的话会出现因 `left++` 导致 `left==right` 已经出现但外层循环还没停止
优化分析：
- 左指针 i+1，右指针 n-1，两者向中间并拢可以得到当前 i 的答案，这样复杂度为 O(n^2)，所以需要优化，将**逻辑上一定不成立的**元素跳过
- 如果 `nums[current] > 0`，那么 `nums[left]` 和 `nums[right]` 一定也>0，没必要判断相加，所以在拿到 current 后立刻判断（1）
![[Pasted image 20250215223318.png|离current最近的2个数 > 0]]
![[Pasted image 20250215223425.png|离current最远的2个数 < 0]]
两种情况（2）（3）不用再比较了，同样在拿到 current 后立刻判断
优化后：
```cpp
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        ranges::sort(nums);
        vector<vector<int>> ans;
        int n = nums.size();
        for (int i = 0;i < n - 2;i++) {
            if (nums[i] > 0) break;// (1)
            int x = nums[i];
            if (i && x == nums[i - 1]) continue;
            if (x + nums[i + 1] + nums[i + 2] > 0) break; // (2)
            if (x + nums[n - 2] + nums[n - 1] < 0) continue;; // (3)
            int left = i + 1, right = n - 1;
            while (left < right) {
                int s = nums[right] + nums[left] + x;
                if (s > 0) right--;
                else if (s < 0) left++;
                else {
                    ans.emplace_back(vector<int>{nums[i], nums[left], nums[right]});
                    for (left++;left < right && nums[left] == nums[left - 1]; left++);
                    for (right--;left < right && nums[right] == nums[right + 1];right--);
                }
            }
        }
        return ans;
    }
};
```

